function LifXXLAiPlayerCharacter::beginCharacterLoad(%this)
{
    if (isObject(NetConnection::findByCharId(%this.charId)))
    {
        %this.fail("CharacterID became registered during DB activation");
        return;
    }

    %connection = new GameConnection("")
    {
        lifxxlAiPlayerLoader = %this;
        lifxxlAiPlayerSynthetic = true;
    };
    if (!%connection.LifXXL_registerAiPlayerConnection(%this.charId))
    {
        %connection.delete();
        %this.fail("CaptainHook rejected the server-local GameConnection");
        return;
    }
    %this.connectionObjectId = %connection.getId();
    %connection.charId = %this.charId;
    %connection.lifxxlAiPlayerAccountId = %this.accountId;
    %connection.registerByCharacter();
    %this.connection = %connection;
    %this.state = "LOADING";
    %connection.initPlayerManager();
    LifXXLAiPlayer.schedule(100, "pollCharacterInfo", %this);
}

{
    cancel(%connection.schDataLoaded);
    %connection.schDataLoaded = "";
}
%datablock = %connection.getPlayerDatablock();
if (%datablock $= "DefaultPlayerData")
{
    %loader.loadAttempts++;
    if (%loader.loadAttempts >= $LifXXLAiPlayer::CharacterLoadMaxAttempts)
    {
        %loader.fail("timed out waiting for CharacterInfo");
        return;
    }
    %this.schedule(
        $LifXXLAiPlayer::CharacterLoadRetryMs,
        "pollCharacterInfo",
        %loader);
    return;
}

%loader.state = "SPAWNING";
%actor = new Player("")
{
    dataBlock = %datablock;
};
if (!isObject(%actor))
{
    %loader.fail("new Player failed");
    return;
}

%loader.actor = %actor;
%actor.client = %connection;
%connection.Player = %actor;
// Live clearScopeAlways on this EXE removed Player objects (2026-10-12).
// Keep until spatial scope and native object lifetime are verified together.
%actor.setScopeAlways();
%connection.setControlObject(%actor);
if (isMethod(Player, setReferencedClient))
{
    %actor.setReferencedClient(%connection);
}
%this.schedule(100, "finishCharacterSpawn", %loader);

{
    %loader.fail("Player did not inherit the expected CharacterID");
    return;
}

if (!%loader.connection.LifXXL_bindAiActor(%loader.actor.getId()))
{
    %loader.fail("native actor binding failed");
    return;
}
%loader.actor.position = %loader.position;
%loader.actor.rotation = "0 0 1 0";
%loader.actor.setProcessTick(1);
%loader.state = "ACTIVE";
LifXXLAiPlayerActive.add(%loader);
echo("LifXXLAiPlayer: spawned CharacterID" SPC %loader.charId SPC
    "(" @ trim(%loader.characterName) @ ") actor=" @ %loader.actor SPC
    "position=" @ %loader.position @ ".");
